--
-- Migration: 0066_release_city_catalog.sql
-- Release upgrade data migration to authoritative 3156-City catalog (27 governorates).
--
DO $$
DECLARE
  official_count int;
  gov_count int;
  invalid_official_count int;
BEGIN
  -- 1. Acquire the City cache fence before changing catalog data
  UPDATE city_catalog_revisions SET revision = revision + 1 WHERE id = 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'City catalog revision state is missing';
  END IF;
  -- Support databases that applied the earlier 0065 schema before this additive field.
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = 'cities' AND column_name = 'governorate_arabic') THEN
    ALTER TABLE cities ADD COLUMN IF NOT EXISTS governorate_arabic varchar(100) NOT NULL DEFAULT '';
  END IF;

  -- 2. Apply reviewed City identity transfers onto existing application UUIDs
  -- (No identity transfers in this release)

  -- 3. Mark newly retired cities as RETIRED
  -- (No retired cities in this release)

  -- 4. Upsert official and updated catalog records

  -- 5. Synchronize denormalized governorate values in posts for official cities
  UPDATE posts SET governorate = cities.governorate FROM cities WHERE posts.city_id = cities.id AND cities.status = 'OFFICIAL';
  UPDATE cities AS city SET governorate_arabic = labels.arabic FROM (VALUES ('Alexandria', 'الاسكندرية'), ('Assiut', 'أسيوط'), ('Aswan', 'أسوان'), ('Behera', 'البحيرة'), ('Beni Suef', 'بنى سويف'), ('Cairo', 'القاهرة'), ('Dakahlia', 'الدقهلية'), ('Damietta', 'دمياط'), ('Fayoum', 'الفيوم'), ('Gharbia', 'الغربية'), ('Giza', 'الجيزة'), ('Ismailia', 'الإسماعيلية'), ('Kafr El-Shikh', 'كفر الشيخ'), ('Kalyoubia', 'القليوبية'), ('Luxor', 'مدينة الأقصر'), ('Matrouh', 'مطروح'), ('Menia', 'المنيا'), ('Menoufia', 'المنوفية'), ('New Valley', 'الوادى الجديد'), ('North Sinai', 'شمال سيناء'), ('Port Said', 'بورسعيد'), ('Qena', 'قنا'), ('Red Sea', 'البحر الأحمر'), ('Sharkia', 'الشرقية'), ('South Sinai', 'جنوب سيناء'), ('Suez', 'السويس'), ('Suhag', 'سوهاج')) AS labels(english, arabic) WHERE city.governorate = labels.english AND city.governorate_arabic IS DISTINCT FROM labels.arabic;

  -- 6. Verification checks: assert exactly 3156 official cities and 27 governorates
  SELECT
    count(*) FILTER (WHERE status = 'OFFICIAL'),
    count(DISTINCT governorate) FILTER (WHERE status = 'OFFICIAL'),
    count(*) FILTER (WHERE status = 'OFFICIAL' AND source_code IS NULL)
  INTO official_count, gov_count, invalid_official_count
  FROM cities;

  IF official_count != 3156 THEN
    RAISE EXCEPTION 'City release verification failed: expected 3156 official cities, found %', official_count;
  END IF;
  IF gov_count != 27 THEN
    RAISE EXCEPTION 'City release verification failed: expected 27 governorates, found %', gov_count;
  END IF;
  IF invalid_official_count != 0 THEN
    RAISE EXCEPTION 'City release verification failed: found % official cities without source_code', invalid_official_count;
  END IF;
END $$;
